def forward(x: R) -> M:
    if isinstance(x, Atom): return MAtom(x.name)
    if isinstance(x, Var): return MVar(x.index)
    if isinstance(x, Box): return MBox(forward(x.body))
    if isinstance(x, Fix): return Mu(forward(x.body))
    raise TypeError(x)

def reverse(x: M) -> R:
