from dataclasses import dataclass
from typing import Tuple
@dataclass(frozen=True)
class Node:
    tag: str
    index: int = 0
    children: Tuple["Node", ...] = ()
def check_scope(node: Node, depth: int = 0) -> bool:
    if node.tag in {"atom", "empty", "unit"}: return True
    if node.tag == "bound": return 0 <= node.index < depth
    if node.tag in {"prod", "arr"}: return all(check_scope(c, depth) for c in node.children)
    if node.tag == "box": return check_scope(node.children[0], depth)
    if node.tag == "fix": return check_scope(node.children[0], depth + 1)
    raise ValueError(f"unknown tag: {node.tag}")

from dataclasses import dataclass
from typing import Tuple
@dataclass(frozen=True)
class Node:
    tag: str
    value: str = ""
    children: Tuple["Node", ...] = ()
FORWARD = {"atom":"atom", "bound":"var", "empty":"bot", "unit":"top",
           "prod":"and", "arr":"imp", "box":"box", "fix":"mu"}
REVERSE = {v:k for k,v in FORWARD.items()}
def translate(node: Node, table: dict[str, str]) -> Node:
    return Node(table[node.tag], node.value,
                tuple(translate(child, table) for child in node.children))
def to_modal(node: Node) -> Node: return translate(node, FORWARD)
def from_modal(node: Node) -> Node: return translate(node, REVERSE)

from typing import FrozenSet, Iterable, Mapping, TypeVar
W = TypeVar("W")
def modal_box(worlds: Iterable[W], successors: Mapping[W, FrozenSet[W]],
              proposition: FrozenSet[W]) -> FrozenSet[W]:
    return frozenset(w for w in worlds if successors.get(w, frozenset()) <= proposition)
def separation_witnesses(worlds: Iterable[W], successors: Mapping[W, FrozenSet[W]],
                         proposition: FrozenSet[W]) -> FrozenSet[W]:
    once = modal_box(worlds, successors, proposition)
    twice = modal_box(worlds, successors, once)
    return once - twice

